import{_ as t,o as l,c as a,b6 as i}from"./chunks/framework.COUcLbTA.js";const u=JSON.parse('{"title":"参考 UI 设计规范设计页面和按钮","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/frontend/multi-product-ui/index.md","filePath":"zh-cn/stage-2/frontend/multi-product-ui/index.md"}'),n={name:"zh-cn/stage-2/frontend/multi-product-ui/index.md"};function s(r,e,o,p,d,h){return l(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="参考-ui-设计规范设计页面和按钮" tabindex="-1">参考 UI 设计规范设计页面和按钮 <a class="header-anchor" href="#参考-ui-设计规范设计页面和按钮" aria-label="Permalink to “参考 UI 设计规范设计页面和按钮”">​</a></h1><p>很多人说&quot;我想让页面更像 Apple 一点&quot;&quot;按钮想做得更高级一点&quot;，但真正开始做时，往往会卡在一个问题上：</p><p><strong>到底该参考什么？</strong></p><p>盯着截图模仿，学到的只是&quot;像不像&quot;。但打开 Apple、Google、Microsoft、Atlassian 的设计规范，你会发现它们真正厉害的地方不是视觉风格，而是<strong>把设计问题讲清楚</strong>：页面先突出什么、按钮如何分级、操作怎么强调——这些判断标准才是核心。</p><blockquote><p>参考设计规范，不是为了做得&quot;像谁&quot;，而是学会别人怎么做判断。</p></blockquote><div class="info custom-block"><p class="custom-block-title">为什么现在还要学这些</p><p>设计规则早已被训练进模型、被设计工具默认吸收，甚至贴几张截图 AI 就能学会。但我们仍然有必要知道这些规则从哪来、为什么这样定。</p></div><h2 id="先看几段原文-感受差距" tabindex="-1">先看几段原文，感受差距 <a class="header-anchor" href="#先看几段原文-感受差距" aria-label="Permalink to “先看几段原文，感受差距”">​</a></h2><p>如果你以前觉得“设计规范不就是讲讲风格吗”，先看几条官方原文。</p><p>平时我们在团队里经常会这样说：</p><ul><li>做个下拉框</li><li>这里放个菜单</li><li>菜单栏加几个功能</li><li>这里放两个按钮，一个确认一个取消</li></ul><p>听起来没问题，但在大厂规范里，这些词都不是模糊概念，而是被拆得非常细。</p><table tabindex="0"><thead><tr><th style="text-align:left;">平时随口说的话</th><th style="text-align:left;">官方原文</th><th style="text-align:left;">简单说</th></tr></thead><tbody><tr><td style="text-align:left;">“做个菜单”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">“A menu reveals its options...”</a></td><td style="text-align:left;"><code>Menu</code> 是拿来做操作的</td></tr><tr><td style="text-align:left;">“菜单栏里放功能”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">“menu bar menus contain all the commands...”</a></td><td style="text-align:left;">这是应用顶部的命令菜单</td></tr><tr><td style="text-align:left;">“做个下拉框”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">“A pop-up list lets the user choose one option among several.”</a></td><td style="text-align:left;"><code>pop-up</code> 是从列表里选一个</td></tr><tr><td style="text-align:left;">“也做个下拉框”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">“A pull-down list is generally used for selecting commands in a specific context.”</a></td><td style="text-align:left;"><code>pull-down</code> 是点开做当前操作</td></tr><tr><td style="text-align:left;">“菜单也能拿来筛选吧”</td><td style="text-align:left;">Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">“If you need to collect information from people, try a select, dropdown, or combobox instead.”</a></td><td style="text-align:left;"><code>Menu</code> 不是拿来选值的</td></tr><tr><td style="text-align:left;">“菜单也能当导航吧”</td><td style="text-align:left;">Material: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">“Menus should not be used as a primary method for navigation within an app.”</a></td><td style="text-align:left;"><code>Menu</code> 不是主导航</td></tr><tr><td style="text-align:left;">“按钮随便写个 OK / Cancel”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">“Always use ‘Cancel’ to title a button that cancels the alert’s action.”</a></td><td style="text-align:left;">按钮文字不能随便写</td></tr></tbody></table><blockquote><p>表格里的引文都可以直接点击，跳到对应的官方页面。</p></blockquote><p>这就是第一次真正看设计规范时最容易被震到的地方：</p><blockquote><p>我们平时以为自己在讨论 UI，实际上很多时候只是在用一堆含糊词交流。</p></blockquote><p>Apple 不会只说“做个菜单”；它会继续区分：</p><ul><li><code>menu</code></li><li><code>menu bar menu</code></li><li><code>pop-up button</code></li><li><code>pull-down button</code></li><li><code>context menu</code></li></ul><p>Fluent 不会只说“下拉框”；它会继续区分：</p><ul><li><code>menu</code></li><li><code>dropdown</code></li><li><code>select</code></li><li><code>combobox</code></li></ul><p>这就是设计规范的必要性。</p><p>它不是为了让页面显得更专业，而是为了让团队在讨论 UI 时，不再每个人脑子里都是不同的东西。</p><h2 id="你将学到" tabindex="-1">你将学到 <a class="header-anchor" href="#你将学到" aria-label="Permalink to “你将学到”">​</a></h2><ol><li>为什么设计页面和按钮时要先看设计规范</li><li>Apple、Material、Fluent、Atlassian 这些规范里，哪些内容最值得参考</li><li>如何把“页面层级”和“按钮层级”设计清楚</li><li>如何让 AI 参考别人的规范来生成页面和按钮</li></ol><h2 id="_1-设计规范为什么能帮你把页面做清楚" tabindex="-1">1. 设计规范为什么能帮你把页面做清楚 <a class="header-anchor" href="#_1-设计规范为什么能帮你把页面做清楚" aria-label="Permalink to “1. 设计规范为什么能帮你把页面做清楚”">​</a></h2><p>看完上面这些原文，你会发现一个关键点：</p><p><strong>设计规范不是锦上添花，而是在先把词说准。</strong></p><p>很多页面不好看，不是因为配色不够高级，而是因为信息层级混乱。</p><p>很多按钮不好用，也不是因为圆角不对，而是因为：</p><ul><li>主按钮太多，用户不知道该点哪个</li><li>危险按钮和普通按钮看起来差不多</li><li>页面里所有按钮都在抢注意力</li><li>不同页面里的按钮样式和语义不一致</li></ul><p>成熟的设计规范，恰好就是在解决这些问题。它们通常会定义：</p><table tabindex="0"><thead><tr><th style="text-align:left;">规范内容</th><th style="text-align:left;">它解决什么问题</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>页面层级</strong></td><td style="text-align:left;">先看哪里、后看哪里，信息怎么组织</td></tr><tr><td style="text-align:left;"><strong>视觉基础</strong></td><td style="text-align:left;">颜色、间距、字体、圆角、阴影怎样统一</td></tr><tr><td style="text-align:left;"><strong>按钮层级</strong></td><td style="text-align:left;">主按钮、次按钮、文字按钮、危险按钮如何区分</td></tr><tr><td style="text-align:left;"><strong>状态规则</strong></td><td style="text-align:left;">hover、focus、disabled、loading 怎么表现</td></tr><tr><td style="text-align:left;"><strong>交互语义</strong></td><td style="text-align:left;">哪个按钮是“确认”，哪个是“取消”，哪个是“更多操作”</td></tr></tbody></table><p>所以，设计规范真正提供的不是一套“皮肤”，而是一套<strong>判断标准</strong>。</p><h2 id="_2-参考大厂规范时-重点看什么" tabindex="-1">2. 参考大厂规范时，重点看什么 <a class="header-anchor" href="#_2-参考大厂规范时-重点看什么" aria-label="Permalink to “2. 参考大厂规范时，重点看什么”">​</a></h2><h3 id="_2-1-参考-apple-学习-定义得足够细-这件事" tabindex="-1">2.1 参考 Apple：学习“定义得足够细”这件事 <a class="header-anchor" href="#_2-1-参考-apple-学习-定义得足够细-这件事" aria-label="Permalink to “2.1 参考 Apple：学习“定义得足够细”这件事”">​</a></h3><p>Apple 最值得学的，不只是视觉上的克制感，而是它会把概念定义得非常细。</p><p>同样是很多团队口中的“菜单”或“下拉框”，Apple 会继续往下拆：</p><ul><li><code>menu</code>：一组命令、选项或状态</li><li><code>menu bar menu</code>：应用级命令集合</li><li><code>pop-up button</code>：选择一个值</li><li><code>pull-down button</code>：在当前上下文里触发命令</li><li><code>context menu</code>：与当前对象或任务相关的常用动作</li></ul><p>这套区分非常重要，因为它会直接影响：</p><ul><li>这个组件是拿来选值，还是拿来做动作</li><li>它属于页面局部，还是属于应用级</li><li>它应该长期显示当前选中值，还是只临时展开命令</li></ul><p>当你开始按这种粒度思考时，你设计出来的页面就会一下子清楚很多。</p><h3 id="_2-2-参考-apple-学习页面层级和克制感" tabindex="-1">2.2 参考 Apple：学习页面层级和克制感 <a class="header-anchor" href="#_2-2-参考-apple-学习页面层级和克制感" aria-label="Permalink to “2.2 参考 Apple：学习页面层级和克制感”">​</a></h3><p>Apple Human Interface Guidelines 特别适合学习两件事：</p><ul><li>页面如何建立清晰层级</li><li>控件如何在不喧宾夺主的前提下保持明确</li></ul><p>Apple 强调 <code>Hierarchy</code>、<code>Harmony</code>、<code>Consistency</code>。这意味着页面设计时要回答：</p><ul><li>当前页面最重要的信息是什么</li><li>用户的主要任务是什么</li><li>哪个操作该最显眼，哪个操作应该退后</li></ul><p>如果你参考 Apple 来设计页面，可以重点借鉴：</p><ul><li>首屏信息不要太碎，核心内容先聚焦</li><li>用留白、字号、分组建立秩序，而不是靠堆很多边框</li><li>按钮不要全部高强调，只有关键动作才应该最突出</li></ul><h3 id="_2-3-参考-material-学习清晰的页面结构" tabindex="-1">2.3 参考 Material：学习清晰的页面结构 <a class="header-anchor" href="#_2-3-参考-material-学习清晰的页面结构" aria-label="Permalink to “2.3 参考 Material：学习清晰的页面结构”">​</a></h3><p>Material Design 很适合学习“页面是怎么组织任务流”的。</p><p>它的很多组件和布局规范，核心都在帮助你明确：</p><ul><li>页面是浏览型，还是执行任务型</li><li>当前页面是让用户阅读、选择，还是提交</li><li>一个页面里哪些元素应该稳定重复，哪些元素应该响应上下文变化</li></ul><p>如果你参考 Material 来设计页面，可以重点借鉴：</p><ul><li>页面区块清楚，模块职责明确</li><li>导航、内容区、操作区分工清晰</li><li>不同按钮样式对应不同操作优先级</li></ul><h3 id="_2-4-参考-fluent-学习组件边界和按钮层级" tabindex="-1">2.4 参考 Fluent：学习组件边界和按钮层级 <a class="header-anchor" href="#_2-4-参考-fluent-学习组件边界和按钮层级" aria-label="Permalink to “2.4 参考 Fluent：学习组件边界和按钮层级”">​</a></h3><p>Fluent 2 很适合后台、工具型产品和复杂表单系统。它最值得学的地方，是会直接告诉你“不要混用概念”。</p><p>例如它明确写到：如果你要“collect information”，就不要继续用 <code>menu</code>，而应该考虑 <code>select</code>、<code>dropdown</code>、<code>combobox</code>。</p><p>这句话非常重要，因为它把很多人脑中的“都差不多”打碎了。</p><p>Fluent 2 也很重视：</p><ul><li>操作层级</li><li>组件语义边界</li><li>密集信息场景下的清晰度</li></ul><p>如果你参考 Fluent 来设计按钮，可以重点借鉴：</p><ul><li><code>Primary button</code> 用来承接当前最重要的动作</li><li><code>Secondary button</code> 用来承接支持性动作</li><li><code>Subtle</code>、<code>Transparent</code> 这类弱强调按钮用于不该抢主流程的操作</li><li>页面里的按钮数量越多，越要控制视觉优先级</li></ul><h3 id="_2-5-参考-atlassian-学习系统化地管理页面和按钮" tabindex="-1">2.5 参考 Atlassian：学习系统化地管理页面和按钮 <a class="header-anchor" href="#_2-5-参考-atlassian-学习系统化地管理页面和按钮" aria-label="Permalink to “2.5 参考 Atlassian：学习系统化地管理页面和按钮”">​</a></h3><p>Atlassian Design System 特别适合“一个团队做很多页面”的情况。它强调：</p><ul><li>foundations 是共享基础</li><li>tokens 是统一视觉决策的方法</li><li>components 是被反复复用的交互构件</li></ul><p>如果你参考 Atlassian 来做页面和按钮，最有价值的是：</p><ul><li>把按钮尺寸、颜色、圆角、间距做成统一规则</li><li>把页面布局的节奏固定下来</li><li>让不同页面虽然内容不同，但结构语言一致</li></ul><h2 id="_3-设计页面时-应该参考规范里的哪些点" tabindex="-1">3. 设计页面时，应该参考规范里的哪些点 <a class="header-anchor" href="#_3-设计页面时-应该参考规范里的哪些点" aria-label="Permalink to “3. 设计页面时，应该参考规范里的哪些点”">​</a></h2><p>当你看一个设计系统时，不要先问“这个页面好不好看”，而要先问下面几个问题。</p><h3 id="_3-1-页面第一眼-主次是不是明确" tabindex="-1">3.1 页面第一眼，主次是不是明确 <a class="header-anchor" href="#_3-1-页面第一眼-主次是不是明确" aria-label="Permalink to “3.1 页面第一眼，主次是不是明确”">​</a></h3><p>一个页面通常至少要有三层：</p><ul><li><strong>主信息</strong>：当前页面最重要的内容</li><li><strong>辅助信息</strong>：帮助理解或补充的内容</li><li><strong>次级操作</strong>：不应该干扰主任务的动作</li></ul><p>如果三层没有拉开，页面就会“都重要”，等于“都不重要”。</p><h3 id="_3-2-页面布局-是不是服务任务而不是堆模块" tabindex="-1">3.2 页面布局，是不是服务任务而不是堆模块 <a class="header-anchor" href="#_3-2-页面布局-是不是服务任务而不是堆模块" aria-label="Permalink to “3.2 页面布局，是不是服务任务而不是堆模块”">​</a></h3><p>参考规范时，可以特别注意：</p><ul><li>标题区有没有明确页面目标</li><li>主内容区是不是围绕任务组织</li><li>操作按钮是不是贴近相关内容</li><li>次要信息有没有被弱化</li></ul><h3 id="_3-3-页面里的操作-是不是有优先级" tabindex="-1">3.3 页面里的操作，是不是有优先级 <a class="header-anchor" href="#_3-3-页面里的操作-是不是有优先级" aria-label="Permalink to “3.3 页面里的操作，是不是有优先级”">​</a></h3><p>很多页面一眼看过去有 6 个按钮，结果每个按钮都像 CTA，这是典型的层级失控。</p><p>更合理的方式是：</p><ul><li>一个区域通常只有一个主动作</li><li>次级动作可以用描边、文字按钮或更弱的样式</li><li>风险动作不要和主动作长得一样</li></ul><h2 id="_4-设计按钮时-应该参考规范里的哪些点" tabindex="-1">4. 设计按钮时，应该参考规范里的哪些点 <a class="header-anchor" href="#_4-设计按钮时-应该参考规范里的哪些点" aria-label="Permalink to “4. 设计按钮时，应该参考规范里的哪些点”">​</a></h2><p>按钮是最容易被“随手设计”的部分，但也是最能暴露系统是否成熟的部分。</p><h3 id="_4-1-按钮先分-语义-再分-样式" tabindex="-1">4.1 按钮先分“语义”，再分“样式” <a class="header-anchor" href="#_4-1-按钮先分-语义-再分-样式" aria-label="Permalink to “4.1 按钮先分“语义”，再分“样式””">​</a></h3><p>不要先想“蓝色按钮还是黑色按钮”，先想这个按钮是什么角色。</p><p>常见按钮角色可以这样分：</p><table tabindex="0"><thead><tr><th style="text-align:left;">按钮类型</th><th style="text-align:left;">作用</th><th style="text-align:left;">常见样式策略</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary</strong></td><td style="text-align:left;">当前区域最关键动作</td><td style="text-align:left;">实心、高对比、最显眼</td></tr><tr><td style="text-align:left;"><strong>Secondary</strong></td><td style="text-align:left;">支持性动作</td><td style="text-align:left;">描边或低一级强调</td></tr><tr><td style="text-align:left;"><strong>Tertiary / Text</strong></td><td style="text-align:left;">弱操作</td><td style="text-align:left;">文字或低视觉占比</td></tr><tr><td style="text-align:left;"><strong>Destructive</strong></td><td style="text-align:left;">删除、停用、清空等风险操作</td><td style="text-align:left;">警示色或明确风险样式</td></tr><tr><td style="text-align:left;"><strong>Icon button</strong></td><td style="text-align:left;">局部工具操作</td><td style="text-align:left;">简洁、靠近上下文</td></tr></tbody></table><h3 id="_4-2-一个页面不要有太多-primary-button" tabindex="-1">4.2 一个页面不要有太多 Primary Button <a class="header-anchor" href="#_4-2-一个页面不要有太多-primary-button" aria-label="Permalink to “4.2 一个页面不要有太多 Primary Button”">​</a></h3><p>这是很多新手最容易踩的坑。</p><p>如果页面上有 4 个主按钮，那么等于没有主按钮。主按钮的意义本来就是“告诉用户现在最应该做什么”。</p><p>你可以借鉴很多设计系统的共同做法：</p><ul><li>一个主要区域通常只保留一个主按钮</li><li>取消、返回、关闭一般不和确认按钮抢同级</li><li>更多操作放到次级按钮或菜单中</li></ul><h3 id="_4-3-按钮要能表达状态变化" tabindex="-1">4.3 按钮要能表达状态变化 <a class="header-anchor" href="#_4-3-按钮要能表达状态变化" aria-label="Permalink to “4.3 按钮要能表达状态变化”">​</a></h3><p>设计规范通常会对按钮状态写得很清楚：</p><ul><li>默认态</li><li>悬停态</li><li>聚焦态</li><li>禁用态</li><li>加载态</li><li>危险态</li></ul><p>这很重要，因为按钮不是一张静态图，而是用户操作过程中最常被触发的控件之一。</p><h3 id="_4-4-按钮文案-也属于设计的一部分" tabindex="-1">4.4 按钮文案，也属于设计的一部分 <a class="header-anchor" href="#_4-4-按钮文案-也属于设计的一部分" aria-label="Permalink to “4.4 按钮文案，也属于设计的一部分”">​</a></h3><p>按钮文案不只是“文案问题”，它直接影响用户理解。</p><p>例如：</p><ul><li><code>保存</code></li><li><code>保存更改</code></li><li><code>立即发布</code></li><li><code>删除项目</code></li><li><code>移到回收站</code></li></ul><p>这些文案传达的心理预期完全不同。成熟规范通常会要求按钮标签清楚表达动作，而不是使用含糊词。</p><h2 id="_5-一个很实用的页面与按钮设计清单" tabindex="-1">5. 一个很实用的页面与按钮设计清单 <a class="header-anchor" href="#_5-一个很实用的页面与按钮设计清单" aria-label="Permalink to “5. 一个很实用的页面与按钮设计清单”">​</a></h2><p>你自己设计页面时，可以先快速过一遍这张清单：</p><h3 id="页面清单" tabindex="-1">页面清单 <a class="header-anchor" href="#页面清单" aria-label="Permalink to “页面清单”">​</a></h3><ul><li>页面标题是否清楚说明当前任务</li><li>首屏最重要的信息是否一眼可见</li><li>页面是不是按任务流程组织，而不是按想到什么放什么</li><li>同一个区域里是否只有一个主要动作</li><li>次要内容是否被适当弱化</li></ul><h3 id="按钮清单" tabindex="-1">按钮清单 <a class="header-anchor" href="#按钮清单" aria-label="Permalink to “按钮清单”">​</a></h3><ul><li>这个按钮是主动作还是次动作</li><li>它为什么值得比别的按钮更显眼</li><li>页面里是不是有太多主按钮</li><li>危险操作是否被明确标识</li><li>按钮文案是否足够具体</li></ul><h2 id="_6-怎样用-ai-参考别人的规范来设计页面" tabindex="-1">6. 怎样用 AI 参考别人的规范来设计页面 <a class="header-anchor" href="#_6-怎样用-ai-参考别人的规范来设计页面" aria-label="Permalink to “6. 怎样用 AI 参考别人的规范来设计页面”">​</a></h2><p>这一节最实用。</p><p>很多人让 AI 设计页面时，只会说：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帮我做一个设置页面，要高级一点，参考苹果风格</span></span></code></pre></div><p>这类提示词太模糊了，AI 最后通常只能模仿“白底、圆角、阴影”。</p><p>对新手来说，更实用的方式不是自己总结一大段，而是直接把<strong>规范原文里的关键句</strong>贴给 AI。</p><p>这样做有两个好处：</p><ul><li>你不用自己先“翻译”一遍设计思想</li><li>AI 更容易按官方定义去理解页面和按钮</li></ul><h3 id="_6-1-例子一-让-ai-参考-apple-设计一个设置页面" tabindex="-1">6.1 例子一：让 AI 参考 Apple 设计一个设置页面 <a class="header-anchor" href="#_6-1-例子一-让-ai-参考-apple-设计一个设置页面" aria-label="Permalink to “6.1 例子一：让 AI 参考 Apple 设计一个设置页面”">​</a></h3><p>先找一句 Apple 原文：</p><blockquote><p><a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p></blockquote><p>你可以直接这样贴给 AI：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参考 Apple Human Interface Guidelines 里的这句话：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帮我设计一个账号安全设置页面。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">要求页面层级清楚，重要信息放前面，分组整齐一点。</span></span></code></pre></div><p>这样写的重点是：不用你自己解释太多，直接把 Apple 的原话贴进去。</p><h3 id="_6-2-例子二-让-ai-参考-fluent-设计后台页面按钮" tabindex="-1">6.2 例子二：让 AI 参考 Fluent 设计后台页面按钮 <a class="header-anchor" href="#_6-2-例子二-让-ai-参考-fluent-设计后台页面按钮" aria-label="Permalink to “6.2 例子二：让 AI 参考 Fluent 设计后台页面按钮”">​</a></h3><p>先找一句 Fluent 原文：</p><blockquote><p><a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>你可以直接这样贴给 AI：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参考 Fluent 2 里的这句话：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帮我设计一个团队管理后台的按钮。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">添加成员按钮最明显，导出、筛选、更多操作弱一点，删除按钮单独突出。</span></span></code></pre></div><p>这一句非常适合新手，因为它直接告诉 AI：一个区域不要放太多主按钮。</p><h3 id="_6-3-例子三-让-ai-同时参考页面规范和按钮规范" tabindex="-1">6.3 例子三：让 AI 同时参考页面规范和按钮规范 <a class="header-anchor" href="#_6-3-例子三-让-ai-同时参考页面规范和按钮规范" aria-label="Permalink to “6.3 例子三：让 AI 同时参考页面规范和按钮规范”">​</a></h3><p>你也可以一次贴两句原文，让 AI 同时参考页面和按钮：</p><blockquote><p>Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p><p>Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>然后直接这样写：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参考下面两句设计规范原文：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apple: &quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fluent: &quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帮我设计一个项目详情页。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">页面包含项目介绍、成员、最近活动和设置入口。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">页面层级清楚一点，主按钮只保留一个，其他按钮弱一点。</span></span></code></pre></div><p>这种方式特别适合新手，因为你只要会复制原文，再加两句自己的需求就够了。</p><h2 id="_7-怎样用-ai-参考按钮规范来直接生成按钮设计" tabindex="-1">7. 怎样用 AI 参考按钮规范来直接生成按钮设计 <a class="header-anchor" href="#_7-怎样用-ai-参考按钮规范来直接生成按钮设计" aria-label="Permalink to “7. 怎样用 AI 参考按钮规范来直接生成按钮设计”">​</a></h2><p>如果你只想先做按钮，也可以直接贴按钮规范原文。</p><p>例如 Atlassian 对按钮的定义很短：</p><blockquote><p><a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">&quot;A button triggers an event or action.&quot;</a></p></blockquote><p>你可以这样问 AI：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参考 Atlassian 的这句话：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A button triggers an event or action.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帮我设计一套后台页面按钮样式。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我要有主按钮、次按钮、删除按钮，顺便告诉我分别用在什么地方。</span></span></code></pre></div><p>这类提示词尤其适合新手，基本就是“贴原文 + 说需求”。</p><h2 id="_8-小结" tabindex="-1">8. 小结 <a class="header-anchor" href="#_8-小结" aria-label="Permalink to “8. 小结”">​</a></h2><p>参考 UI 设计规范设计页面和按钮，最重要的不是“做得像谁”，而是学会下面这几件事：</p><ol><li>用层级组织页面，而不是把内容堆上去</li><li>用按钮分级表达操作优先级，而不是让所有按钮都一样抢眼</li><li>用设计规范里的定义、边界和判断标准指导设计</li><li>让 AI 参考别人规范时，参考的是“原则和结构”，而不是只参考皮肤</li></ol><p>当你这样使用规范时，你参考到的就不只是一个风格，而是一套成熟的设计思考方式。</p><hr><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><p>以下链接都来自官方设计系统或官方文档：</p><ul><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">Overview</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">Menus</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">Alerts</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/buttons" target="_blank" rel="noreferrer">Buttons</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/HowMenusWork.html" target="_blank" rel="noreferrer">How Menus Work</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">Managing Pop-Up Buttons and Pull-Down Lists</a></li><li>Material Design: <a href="https://m3.material.io/components/buttons/overview" target="_blank" rel="noreferrer">Buttons overview</a></li><li>Material Design: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">Menus</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/get-started/design" target="_blank" rel="noreferrer">Start designing</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">Menu usage</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">Button usage</a></li><li>Atlassian Design System: <a href="https://atlassian.design/foundations/" target="_blank" rel="noreferrer">Foundations</a></li><li>Atlassian Design System: <a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">Button</a></li></ul>`,146)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
